mapper.select:
SELECT COUNT(id) FROM moving_order

    order_status = #{status}

        AND create_time BETWEEN #{startDate} AND #{endDate}

SELECT SUM(moving_price) FROM moving_order

    is_paid = 1

        AND payment_time BETWEEN #{startDate} AND #{endDate}

SELECT AVG(moving_price) FROM moving_order

    order_status = 4 AND is_paid = 1

        AND moving_end_time BETWEEN #{startDate} AND #{endDate}

SELECT
DATE_FORMAT(create_time, '%Y-%m-%d') DATE_FORMAT(create_time, '%X-%V') DATE_FORMAT(create_time, '%Y-%m') DATE_FORMAT(create_time, '%Y-%m-%d')
AS dateLabel, COUNT(id) AS count FROM ${userTable}
AND create_time BETWEEN #{startDate} AND #{endDate}
GROUP BY dateLabel ORDER BY dateLabel

SELECT order_status AS status, COUNT(id) AS count FROM moving_order
AND create_time BETWEEN #{startDate} AND #{endDate}
GROUP BY order_status ORDER BY order_status

choose.when:
SELECT s.service_name AS name, COUNT(mo.id) AS count FROM moving_order mo JOIN service s ON mo.service_id = s.id
AND mo.create_time BETWEEN #{startDate} AND #{endDate}
GROUP BY mo.service_id, s.service_name ORDER BY count DESC

SELECT tt.type_name AS name, COUNT(mo.id) AS count FROM moving_order mo JOIN truck_type tt ON mo.truck_type_id = tt.id
AND mo.create_time BETWEEN #{startDate} AND #{endDate}
GROUP BY mo.truck_type_id, tt.type_name ORDER BY count DESC

mapper.select:
SELECT rating_value AS ratingValue, COUNT(id) AS count FROM rating
AND rating_time BETWEEN #{startDate} AND #{endDate}
AND rating_type = #{ratingType}
GROUP BY rating_value ORDER BY rating_value

SELECT COUNT(id)
FROM rating


        AND rating_time BETWEEN #{startDate} AND #{endDate}


        AND rating_type = #{ratingType}

SELECT id, name, average_rating AS averageRating, rating_count AS ratingCount FROM driver
is_banned = 0
AND rating_count >= #{minRatingCount}
ORDER BY average_rating DESC, rating_count DESC
LIMIT #{limit}

SELECT id, name, average_rating AS averageRating, rating_count AS ratingCount FROM mover
is_banned = 0
AND rating_count >= #{minRatingCount}
ORDER BY average_rating DESC, rating_count DESC
LIMIT #{limit}

SELECT id, service_name AS serviceName, average_rating AS averageRating, rating_count AS ratingCount FROM service
status = 1
AND rating_count >= #{minRatingCount}
ORDER BY average_rating DESC, rating_count DESC
LIMIT #{limit}
